import 'dart:convert';
import 'dart:math';
import 'package:cryptography/cryptography.dart';
import '../source_models.dart';

class SyncVersion {
  SyncVersion(this.clock, this.value);
  final Map<String, int> clock;
  final Map<String, dynamic> value;
  Map<String, dynamic> toJson() => {'clock': clock, 'value': value};
  factory SyncVersion.fromJson(Map<String, dynamic> json) {
    final raw = sourceMap(json['clock']);
    if (raw.isEmpty || raw.length > 128 || json['value'] is! Map) {
      throw const SourceException(SourceFailure.invalidData);
    }
    final clock = <String, int>{};
    for (final e in raw.entries) {
      if (!RegExp(r'^[a-f0-9]{32}$').hasMatch(e.key) ||
          e.value is! int || e.value <= 0 || e.value > 9007199254740991) {
        throw const SourceException(SourceFailure.invalidData);
      }
      clock[e.key] = e.value as int;
    }
    return SyncVersion(clock, sourceMap(json['value']));
  }
}

String canonicalSyncJson(Object? value) {
  Object? sorted(Object? v) {
    if (v is Map) {
      final keys = v.keys.cast<String>().toList()..sort();
      return {for (final k in keys) k: sorted(v[k])};
    }
    if (v is List) return v.map(sorted).toList();
    return v;
  }
  return jsonEncode(sorted(value));
}

Map<String, int> joinedClock(Iterable<SyncVersion> values) {
  final result = <String, int>{};
  for (final v in values) {
    for (final e in v.clock.entries) {
      if (e.value > (result[e.key] ?? 0)) result[e.key] = e.value;
    }
  }
  return result;
}

bool _covers(Map<String, int> a, Map<String, int> b) =>
    b.entries.every((e) => (a[e.key] ?? 0) >= e.value);

/// Multi-value register: only causally newer values supersede prior values.
/// Neither wall-clock time nor furthest progress selects a winner.
class SyncDocument {
  SyncDocument([Map<String, List<SyncVersion>>? records]) : records = records ?? {};
  final Map<String, List<SyncVersion>> records;
  static const maxRecords = 20000;
  static const maxBytes = 4 * 1024 * 1024;

  void merge(SyncDocument other) {
    for (final e in other.records.entries) {
      for (final incoming in e.value) {
        final current = records.putIfAbsent(e.key, () => []);
        var covered = false;
        for (final old in current) {
          if (_covers(old.clock, incoming.clock)) {
            if (_covers(incoming.clock, old.clock) &&
                canonicalSyncJson(old.value) != canonicalSyncJson(incoming.value)) {
              throw const SourceException(SourceFailure.invalidData);
            }
            covered = true;
          }
        }
        if (covered) continue;
        current.removeWhere((old) => _covers(incoming.clock, old.clock));
        current.add(incoming);
        current.sort((a, b) => canonicalSyncJson(a.clock).compareTo(canonicalSyncJson(b.clock)));
        if (current.length > 128 || records.length > maxRecords) {
          throw const SourceException(SourceFailure.invalidData);
        }
      }
    }
  }

  /// The basis is the last value applied locally, not every downloaded value.
  /// Remote progress deferred by an active reader must remain concurrent.
  SyncVersion edit(String key, String device, Map<String, dynamic> value, Map<String, int> basis) {
    final existing = records[key] ?? [];
    final clock = Map<String, int>.from(basis);
    final seen = joinedClock(existing)[device] ?? 0;
    clock[device] = (seen > (clock[device] ?? 0) ? seen : (clock[device] ?? 0)) + 1;
    if (clock.length > 128) throw const SourceException(SourceFailure.invalidData);
    final next = SyncVersion(clock, value);
    merge(SyncDocument({key: [next]}));
    return next;
  }

  bool conflicted(String key) =>
      (records[key] ?? []).map((v) => canonicalSyncJson(v.value)).toSet().length > 1;
  Map<String, dynamic> toJson() => {
    'version': 1,
    'records': records.map((k, v) => MapEntry(k, v.map((x) => x.toJson()).toList())),
  };
  factory SyncDocument.fromJson(Map<String, dynamic> json) {
    if (json['version'] != 1) throw const SourceException(SourceFailure.unsupported);
    final raw = sourceMap(json['records']);
    if (raw.length > maxRecords) throw const SourceException(SourceFailure.invalidData);
    final result = SyncDocument();
    for (final e in raw.entries) {
      if (!RegExp(r'^[a-f0-9]{64}$').hasMatch(e.key) || e.value is! List ||
          (e.value as List).isEmpty || (e.value as List).length > 128) {
        throw const SourceException(SourceFailure.invalidData);
      }
      result.merge(SyncDocument({
        e.key: (e.value as List).map((v) => SyncVersion.fromJson(sourceMap(v))).toList(),
      }));
    }
    return result;
  }
}

/// A random 256-bit join code encrypts all progress and annotations.
/// Filenames are authenticated; tokens and media never enter the document.
class SyncCipher {
  SyncCipher(String code) : keyBytes = decodeCode(code);
  final List<int> keyBytes;
  static final _algorithm = AesGcm.with256bits();
  static String newCode() {
    final random = Random.secure();
    return base64UrlEncode(List.generate(32, (_) => random.nextInt(256))).replaceAll('=', '');
  }
  static List<int> decodeCode(String code) {
    try {
      final bytes = base64Url.decode(base64Url.normalize(code.trim()));
      if (bytes.length != 32) throw const FormatException();
      return bytes;
    } catch (_) {
      throw const SourceException(SourceFailure.invalidData);
    }
  }
  String get namespace => sourceDigest(base64UrlEncode(keyBytes)).substring(0, 24);
  Future<String> seal(SyncDocument document, String name) async {
    final bytes = utf8.encode(canonicalSyncJson(document.toJson()));
    if (bytes.length > SyncDocument.maxBytes) throw const SourceException(SourceFailure.invalidData);
    final box = await _algorithm.encrypt(bytes, secretKey: SecretKey(keyBytes), aad: utf8.encode(name));
    return jsonEncode({
      'version': 1, 'nonce': base64Encode(box.nonce),
      'ciphertext': base64Encode(box.cipherText), 'mac': base64Encode(box.mac.bytes),
    });
  }
  Future<SyncDocument> open(String text, String name) async {
    try {
      if (utf8.encode(text).length > 6 * 1024 * 1024) throw const FormatException();
      final json = sourceMap(jsonDecode(text));
      if (json['version'] != 1) throw const SourceException(SourceFailure.unsupported);
      final nonce = base64Decode(json['nonce'] as String), mac = base64Decode(json['mac'] as String);
      if (nonce.length != 12 || mac.length != 16) throw const FormatException();
      final clear = await _algorithm.decrypt(
        SecretBox(base64Decode(json['ciphertext'] as String), nonce: nonce, mac: Mac(mac)),
        secretKey: SecretKey(keyBytes), aad: utf8.encode(name),
      );
      if (clear.length > SyncDocument.maxBytes) throw const FormatException();
      return SyncDocument.fromJson(sourceMap(jsonDecode(utf8.decode(clear))));
    } on SourceException {
      rethrow;
    } catch (_) {
      throw const SourceException(SourceFailure.invalidData);
    }
  }
}

import 'dart:convert';
import 'package:xml/xml.dart';
import 'package:uuid/uuid.dart';
import '../adapters/cloud_sources.dart';
import '../adapters/s3_source.dart';
import '../adapters/webdav_source.dart';
import '../source_models.dart';
import '../source_transport.dart';

class SyncFile {
  const SyncFile(this.name, this.id);
  final String name;
  final String id;
  static final pattern = RegExp(r'^plezyng-state-v1-([a-f0-9]{24})-([a-f0-9]{32})-([0-9]{16})\.json$');
  String get device => pattern.firstMatch(name)!.group(2)!;
  int get sequence => int.parse(pattern.firstMatch(name)!.group(3)!);
  static String filename(String namespace, String device, int sequence) =>
      'plezyng-state-v1-$namespace-$device-${sequence.toString().padLeft(16, '0')}.json';
}

abstract class SyncStore {
  Future<List<SyncFile>> list(String namespace);
  Future<String> read(SyncFile file);
  Future<void> create(String name, String text);
  Future<void> delete(SyncFile file);
}

/// Immutable generations avoid shared-file overwrite races. Only this device's
/// older generations can be pruned after a successful publish.
class ProviderSyncStore implements SyncStore {
  ProviderSyncStore(this.adapter, {this.folder = '', this.check = _noop});
  final SourceAdapter adapter;
  final String folder;
  final void Function() check;
  static void _noop() {}
  SourceTransport get transport => adapter.transport;
  FileSourceKind get kind => adapter.source.kind;
  static bool supports(FileSourceKind kind) => const {
    FileSourceKind.googleDrive, FileSourceKind.oneDrive, FileSourceKind.dropbox,
    FileSourceKind.webdav, FileSourceKind.s3,
  }.contains(kind);
  final Map<String, Set<String>> _listed = {};
  String _prefix(String namespace) => 'plezyng-state-v1-$namespace-';
  void _name(String name) {
    check();
    if (!SyncFile.pattern.hasMatch(name)) throw const SourceException(SourceFailure.invalidData);
  }
  void _file(SyncFile file) {
    _name(file.name);
    if (!(_listed[file.name]?.contains(file.id) ?? false)) {
      throw const SourceException(SourceFailure.permission);
    }
  }
  Future<Map<String, String>> _headers() async {
    check();
    final a = adapter;
    if (a is OAuthSourceAdapter) return {'Authorization': 'Bearer ${await a.token(refresh: false)}'};
    if (a is WebDavSourceAdapter) return a.headers();
    return {};
  }
  Uri _graph(String path) => Uri.https('graph.microsoft.com', '/v1.0/me/drive$path');
  Uri _dropbox(String action, {bool content = false}) =>
      Uri.https(content ? 'content.dropboxapi.com' : 'api.dropboxapi.com', '/2/files/$action');
  Future<Map<String, dynamic>> _json(String method, Uri uri, {Object? body}) async {
    check();
    return (adapter as OAuthSourceAdapter).api(method, uri, body: body);
  }
  Uri get _davRoot {
    if (folder.trim().isEmpty) throw const SourceException(SourceFailure.invalidData);
    return (adapter as WebDavSourceAdapter).contained('${folder.replaceAll(RegExp(r'/+$'), '')}/');
  }
  String get _s3Prefix {
    final base = adapter.source.root.replaceAll(RegExp(r'^/+|/+$'), '');
    final relative = folder.replaceAll(RegExp(r'^/+|/+$'), '');
    if (relative.isEmpty || relative.contains('\\') ||
        relative.split('/').any((s) => s == '.' || s == '..' || s.isEmpty)) {
      throw const SourceException(SourceFailure.invalidData);
    }
    return '${base.isEmpty ? '' : '$base/'}$relative/';
  }
  Future<Uri> _s3(String method, {String? key, Map<String, String>? query}) async {
    final a = adapter as S3SourceAdapter;
    final base = Uri.parse(a.source.endpoint);
    final uri = base.replace(
      pathSegments: [...base.pathSegments.where((s) => s.isNotEmpty), if (key != null) ...key.split('/')],
      queryParameters: query,
    );
    final credentials = await a.credentials();
    check();
    return S3SourceAdapter.sign(
      uri: uri, method: method, accessKey: credentials['accessKey'] ?? '',
      secretKey: credentials['secretKey'] ?? '', region: a.source.options['region'] ?? 'us-east-1',
      sessionToken: credentials['sessionToken'], time: DateTime.now(),
    );
  }
  void _add(List<SyncFile> files, String namespace, String name, String id) {
    if (!name.startsWith(_prefix(namespace)) || !SyncFile.pattern.hasMatch(name)) return;
    if (files.length >= 2048) throw const SourceException(SourceFailure.invalidData);
    _listed.putIfAbsent(name, () => {}).add(id);
    files.add(SyncFile(name, id));
  }

  @override
  Future<List<SyncFile>> list(String namespace) async {
    check();
    if (!RegExp(r'^[a-f0-9]{24}$').hasMatch(namespace)) throw const SourceException(SourceFailure.invalidData);
    _listed.clear();
    final result = <SyncFile>[];
    final cursors = <String>{};
    String? cursor;
    do {
      check();
      if (cursor != null && (!cursors.add(cursor) || cursors.length > 64)) {
        throw const SourceException(SourceFailure.invalidData);
      }
      switch (kind) {
        case FileSourceKind.googleDrive:
          final data = await _json('GET', Uri.https('www.googleapis.com', '/drive/v3/files', {
            'spaces': 'appDataFolder', 'q': "trashed = false and name contains '${_prefix(namespace)}'",
            'pageSize': '1000', 'fields': 'nextPageToken,files(id,name)', 'pageToken': ?cursor,
          }));
          for (final raw in sourceList(data['files'])) {
            final row = sourceMap(raw);
            _add(result, namespace, row['name'] as String, row['id'] as String);
          }
          cursor = data['nextPageToken'] as String?;
        case FileSourceKind.oneDrive:
          final uri = cursor == null
              ? _graph('/special/approot/children').replace(queryParameters: {'\$top': '200', '\$select': 'id,name'})
              : Uri.parse(cursor);
          if (uri.scheme != 'https' || uri.host != 'graph.microsoft.com' ||
              uri.port != 443 || uri.userInfo.isNotEmpty) {
            throw const SourceException(SourceFailure.permission);
          }
          final data = await _json('GET', uri);
          for (final raw in sourceList(data['value'])) {
            final row = sourceMap(raw);
            _add(result, namespace, row['name'] as String, row['id'] as String);
          }
          cursor = data['@odata.nextLink'] as String?;
        case FileSourceKind.dropbox:
          Map<String, dynamic> data;
          try {
            data = await _json('POST', _dropbox(cursor == null ? 'list_folder' : 'list_folder/continue'),
              body: cursor == null ? {'path': '/PlezyNG Sync', 'limit': 1000} : {'cursor': cursor});
          } on SourceException catch (e) {
            if (e.status != 409 || cursor != null) rethrow;
            await _json('POST', _dropbox('create_folder_v2'),
              body: {'path': '/PlezyNG Sync', 'autorename': false});
            data = await _json('POST', _dropbox('list_folder'),
              body: {'path': '/PlezyNG Sync', 'limit': 1000});
          }
          for (final raw in sourceList(data['entries'])) {
            final row = sourceMap(raw);
            if (row['.tag'] == 'file') _add(result, namespace, row['name'] as String, row['id'] as String);
          }
          cursor = data['has_more'] == true ? data['cursor'] as String? : null;
        case FileSourceKind.webdav:
          final root = _davRoot;
          final text = await transport.text('PROPFIND', root,
            headers: {...await _headers(), 'Depth': '1', 'Content-Type': 'application/xml'},
            body: '<d:propfind xmlns:d="DAV:"><d:prop><d:resourcetype/></d:prop></d:propfind>');
          final xml = XmlDocument.parse(text);
          for (final row in xml.descendants.whereType<XmlElement>().where((e) => e.name.local == 'response')) {
            final href = row.descendants.whereType<XmlElement>()
                .where((e) => e.name.local == 'href').firstOrNull?.innerText;
            if (href == null) continue;
            final uri = root.resolve(href);
            if (!sameSourceOrigin(root, uri) || uri.hasQuery || uri.hasFragment || uri.userInfo.isNotEmpty) continue;
            final name = uri.pathSegments.lastOrNull ?? '';
            if (uri.path != root.resolve(Uri(pathSegments: [name]).toString()).path) continue;
            _add(result, namespace, name, uri.toString());
          }
          cursor = null;
        case FileSourceKind.s3:
          final prefix = '$_s3Prefix${_prefix(namespace)}';
          final xml = XmlDocument.parse(await transport.text('GET', await _s3('GET', query: {
            'list-type': '2', 'prefix': prefix, 'max-keys': '1000', 'continuation-token': ?cursor,
          })));
          for (final row in xml.descendants.whereType<XmlElement>().where((e) => e.name.local == 'Contents')) {
            final key = row.childElements.where((e) => e.name.local == 'Key').firstOrNull?.innerText;
            if (key != null && key.startsWith(_s3Prefix)) {
              _add(result, namespace, key.substring(_s3Prefix.length), key);
            }
          }
          cursor = xml.rootElement.childElements
              .where((e) => e.name.local == 'NextContinuationToken').firstOrNull?.innerText;
          if (cursor?.isEmpty == true) cursor = null;
        default:
          throw const SourceException(SourceFailure.unsupported);
      }
    } while (cursor != null);
    check();
    return result;
  }

  @override
  Future<String> read(SyncFile file) async {
    _file(file);
    switch (kind) {
      case FileSourceKind.googleDrive:
        return transport.text('GET',
          Uri.https('www.googleapis.com', '/drive/v3/files/${file.id}', {'alt': 'media'}),
          headers: await _headers(), limit: 6 * 1024 * 1024);
      case FileSourceKind.oneDrive:
        return transport.text('GET', _graph('/items/${file.id}/content'),
          headers: await _headers(), redirects: true, limit: 6 * 1024 * 1024);
      case FileSourceKind.dropbox:
        return transport.text('POST', _dropbox('download', content: true),
          headers: {...await _headers(), 'Dropbox-API-Arg': jsonEncode({'path': file.id})},
          limit: 6 * 1024 * 1024);
      case FileSourceKind.webdav:
        return transport.text('GET', Uri.parse(file.id), headers: await _headers(), limit: 6 * 1024 * 1024);
      case FileSourceKind.s3:
        return transport.text('GET', await _s3('GET', key: file.id), limit: 6 * 1024 * 1024);
      default:
        throw const SourceException(SourceFailure.unsupported);
    }
  }

  @override
  Future<void> create(String name, String text) async {
    _name(name);
    if (utf8.encode(text).length > 6 * 1024 * 1024) throw const SourceException(SourceFailure.invalidData);
    switch (kind) {
      case FileSourceKind.googleDrive:
        final boundary = 'plezyng-${const Uuid().v4()}';
        await transport.text('POST',
          Uri.https('www.googleapis.com', '/upload/drive/v3/files', {'uploadType': 'multipart'}),
          headers: {...await _headers(), 'Content-Type': 'multipart/related; boundary=$boundary'},
          body: '--$boundary\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${jsonEncode({'name': name, 'parents': ['appDataFolder'], 'mimeType': 'application/json'})}\r\n--$boundary\r\nContent-Type: application/json\r\n\r\n$text\r\n--$boundary--\r\n');
      case FileSourceKind.oneDrive:
        await transport.text('PUT', _graph('/special/approot:/$name:/content'),
          headers: {...await _headers(), 'Content-Type': 'application/json', 'If-None-Match': '*'}, body: text);
      case FileSourceKind.dropbox:
        await transport.text('POST', _dropbox('upload', content: true),
          headers: {...await _headers(), 'Content-Type': 'application/octet-stream',
            'Dropbox-API-Arg': jsonEncode({'path': '/PlezyNG Sync/$name', 'mode': 'add',
              'autorename': false, 'mute': true, 'strict_conflict': true})}, body: text);
      case FileSourceKind.webdav:
        await transport.text('PUT', _davRoot.resolve(name),
          headers: {...await _headers(), 'Content-Type': 'application/json', 'If-None-Match': '*'}, body: text);
      case FileSourceKind.s3:
        await transport.text('PUT', await _s3('PUT', key: '$_s3Prefix$name'),
          headers: {'Content-Type': 'application/json', 'If-None-Match': '*'}, body: text);
      default:
        throw const SourceException(SourceFailure.unsupported);
    }
    check();
  }

  @override
  Future<void> delete(SyncFile file) async {
    _file(file);
    switch (kind) {
      case FileSourceKind.googleDrive:
        await transport.text('DELETE', Uri.https('www.googleapis.com', '/drive/v3/files/${file.id}'),
          headers: await _headers());
      case FileSourceKind.oneDrive:
        await transport.text('DELETE', _graph('/items/${file.id}'), headers: await _headers());
      case FileSourceKind.dropbox:
        await _json('POST', _dropbox('delete_v2'), body: {'path': file.id});
      case FileSourceKind.webdav:
        await transport.text('DELETE', Uri.parse(file.id), headers: await _headers());
      case FileSourceKind.s3:
        await transport.text('DELETE', await _s3('DELETE', key: file.id));
      default:
        throw const SourceException(SourceFailure.unsupported);
    }
  }
}

import 'dart:convert';
import 'package:drift/drift.dart';
import 'package:uuid/uuid.dart';
import '../source_database.dart';
import '../source_models.dart';
import 'sync_document.dart';
import 'sync_store.dart';

class PublicationSyncConfig {
  const PublicationSyncConfig({required this.sourceId, required this.code, this.folder = ''});
  final String sourceId;
  final String code;
  final String folder;
  Map<String, dynamic> toJson() => {'sourceId': sourceId, 'code': code, 'folder': folder};
  factory PublicationSyncConfig.fromJson(Map<String, dynamic> j) => PublicationSyncConfig(
    sourceId: j['sourceId'] as String, code: j['code'] as String, folder: j['folder'] as String? ?? '');
}
class PublicationSyncConflict {
  PublicationSyncConflict(this.key, this.entry, this.values);
  final String key;
  final SourceEntry entry;
  final List<SyncVersion> values;
}
class _LocalValue {
  _LocalValue(this.value, this.localKey, this.entry);
  final Map<String, dynamic> value;
  final String localKey;
  final SourceEntry entry;
}
class _SyncCache {
  _SyncCache(Map<String, dynamic> j)
    : document = j['document'] == null ? SyncDocument() : SyncDocument.fromJson(sourceMap(j['document'])),
      observed = sourceMap(j['observed']).map((k, v) => MapEntry(k, v as String)),
      basis = sourceMap(j['basis']).map((k, v) => MapEntry(k, sourceMap(v).map((a, b) => MapEntry(a, b as int)))),
      sequence = sourceInt(j['sequence']) ?? 0,
      published = j['published'] as String? ?? '';
  final SyncDocument document;
  final Map<String, String> observed;
  final Map<String, Map<String, int>> basis;
  int sequence;
  String published;
  Map<String, dynamic> toJson() => {
    'document': document.toJson(), 'observed': observed, 'basis': basis,
    'sequence': sequence, 'published': published,
  };
}

/// Profile-scoped replication. Local rows and their import baseline commit
/// together. All network results are checked against the owning session.
class PublicationSync {
  PublicationSync(this.repository);
  final SourceRepository repository;
  final Map<String, PublicationSyncConflict> conflicts = {};
  bool running = false;
  SourceFailure? failure;
  DateTime? lastSuccess;
  static const configKey = 'publication-sync-config-v1';
  static String _cacheKey(String namespace) => 'publication-sync-cache-v1:$namespace';
  void resetStatus() { conflicts.clear(); failure = null; lastSuccess = null; }
  Future<PublicationSyncConfig?> config(String profile) async {
    final json = await repository.privatePreference(profile, configKey);
    return json.isEmpty ? null : PublicationSyncConfig.fromJson(json);
  }
  Future<void> configure(String profile, PublicationSyncConfig? value) async {
    if (value == null) {
      await repository.forgetPreference(profile, configKey);
      resetStatus();
      return;
    }
    SyncCipher(value.code);
    await repository.savePrivatePreference(profile, configKey, value.toJson());
    resetStatus();
  }
  static String entryIdentity(FileSource source, SourceEntry entry) {
    final library = source.options['syncLibrary'];
    return sourceDigest(canonicalSyncJson([
      source.kind.name,
      library?.isNotEmpty == true ? library :
        source.kind == FileSourceKind.local ? source.root :
        source.endpoint.replaceAll(RegExp(r'/+$'), ''),
      source.options['driveId'] ?? '', entry.id,
    ]));
  }
  static String progressKey(String entry, String edition, PublicationMode mode) =>
      sourceDigest(jsonEncode(['progress', entry, edition, mode.name]));
  static Map<String, dynamic> _progressValue(String identity, PublicationProgress p) => {
    'type': 'progress', 'entry': identity,
    'data': {...p.toJson()}..remove('entryKey')..remove('session')..remove('revision')..remove('updatedAt'),
  };
  static Map<String, dynamic> _annotationValue(String identity, BookAnnotation a) => {
    'type': 'annotation', 'entry': identity,
    'data': {...a.toJson()}..remove('entryKey')..remove('updatedAt'),
  };
  static String _hash(Map<String, dynamic> value) => sourceDigest(canonicalSyncJson(value));

  Future<Map<String, _LocalValue>> _locals(
    String profile, List<FileSource> sources, List<SourceEntry> entries,
  ) async {
    final identities = <String, String>{};
    for (final entry in entries) {
      final source = sources.where((s) => s.id == entry.sourceId).firstOrNull;
      if (source != null) identities[entry.key] = entryIdentity(source, entry);
    }
    final byKey = {for (final e in entries) e.key: e};
    final values = <String, _LocalValue>{};
    for (final p in await repository.allProgress(profile)) {
      final identity = identities[p.entryKey];
      if (identity != null) {
        values[progressKey(identity, p.edition, p.mode)] =
          _LocalValue(_progressValue(identity, p), p.key, byKey[p.entryKey]!);
      }
    }
    final rows = await repository.database.customSelect(
      'SELECT payload FROM annotations WHERE profile=?', variables: [Variable(profile)],
    ).get();
    for (final row in rows) {
      final a = BookAnnotation.fromJson(sourceMap(jsonDecode(row.read<String>('payload'))));
      final identity = identities[a.entryKey];
      if (identity != null) {
        values[sourceDigest(jsonEncode(['annotation', identity, a.id]))] =
          _LocalValue(_annotationValue(identity, a), a.id, byKey[a.entryKey]!);
      }
    }
    return values;
  }
  void _capture(_SyncCache cache, String device, Map<String, _LocalValue> locals) {
    for (final e in locals.entries) {
      final hash = _hash(e.value.value);
      if (cache.observed[e.key] == hash) continue;
      final next = cache.document.edit(e.key, device, e.value.value, cache.basis[e.key] ?? {});
      cache.basis[e.key] = next.clock;
      cache.observed[e.key] = hash;
    }
  }
  Map<String, SourceEntry> _identities(List<FileSource> sources, List<SourceEntry> entries) => {
    for (final e in entries)
      if (sources.any((s) => s.id == e.sourceId))
        entryIdentity(sources.firstWhere((s) => s.id == e.sourceId), e): e,
  };
  bool _compatible(SourceEntry entry, Map<String, dynamic> data) {
    final edition = data['edition'], mode = data['mode'];
    if (mode == PublicationMode.reading.name) return entry.ebooks.any((f) => f.fingerprint == edition);
    final groups = <List<PublicationFile>>[entry.audio, for (final f in entry.files) [f]];
    return const ['listening', 'watching'].contains(mode) &&
      groups.where((g) => g.isNotEmpty).any(
        (g) => sourceDigest(jsonEncode(g.map((f) => f.fingerprint).toList())) == edition);
  }
  Future<void> _apply(String profile, _SyncCache cache,
    Map<String, SourceEntry> identities, Set<String> activeKeys,
  ) async {
    conflicts.clear();
    for (final record in cache.document.records.entries) {
      final values = record.value;
      final first = values.first.value;
      final entry = identities[first['entry']];
      if (entry == null) continue;
      for (final v in values) {
        if (v.value['entry'] != first['entry'] || v.value['type'] != first['type']) {
          throw const SourceException(SourceFailure.invalidData);
        }
      }
      if (cache.document.conflicted(record.key)) {
        conflicts[record.key] = PublicationSyncConflict(record.key, entry, values);
        continue;
      }
      final data = sourceMap(first['data']);
      if (!_compatible(entry, data)) continue;
      final hash = _hash(first);
      if (cache.observed[record.key] == hash) {
        cache.basis[record.key] = joinedClock(values);
        continue;
      }
      if (first['type'] == 'progress') {
        final value = PublicationProgress.fromJson({
          ...data, 'entryKey': entry.key, 'session': const Uuid().v4(),
        });
        if (value.positionMs < 0 || value.filePositionMs < 0 || value.fileIndex < 0 ||
            value.fileIndex >= entry.files.length || !value.speed.isFinite) {
          throw const SourceException(SourceFailure.invalidData);
        }
        if (activeKeys.contains(value.key)) continue;
        final current = await repository.progress(profile, value.key);
        final saved = await repository.saveProgress(
          profile, value.copyWith(revision: current?.revision ?? 0), kind: 'cloud');
        await repository.acknowledge(profile, saved.key, saved.revision);
      } else if (first['type'] == 'annotation') {
        final a = BookAnnotation.fromJson({
          ...data, 'entryKey': entry.key, 'updatedAt': DateTime.now().millisecondsSinceEpoch,
        });
        if (a.note.length > 100000 || a.quote.length > 100000 || a.id.length > 200) {
          throw const SourceException(SourceFailure.invalidData);
        }
        await repository.database.customStatement(
          'INSERT OR REPLACE INTO annotations VALUES (?,?,?,?)',
          [profile, a.id, a.entryKey, jsonEncode(a.toJson())]);
      } else {
        throw const SourceException(SourceFailure.invalidData);
      }
      cache.observed[record.key] = hash;
      cache.basis[record.key] = joinedClock(values);
    }
  }

  Future<void> run({
    required String profile, required List<FileSource> sources,
    required PublicationSyncConfig config, required SyncStore store,
    required Set<String> activeKeys, required void Function() check,
  }) async {
    if (running) throw const SourceException(SourceFailure.conflict);
    running = true;
    failure = null;
    try {
      check();
      final cipher = SyncCipher(config.code);
      final cacheKey = _cacheKey(cipher.namespace);
      final cache = _SyncCache(await repository.preference(profile, cacheKey));
      final deviceConfig = await repository.preference(profile, 'publication-sync-device-v1');
      final device = deviceConfig['id'] as String? ?? const Uuid().v4().replaceAll('-', '');
      check();
      await repository.savePreference(profile, 'publication-sync-device-v1', {'id': device});
      final entries = await repository.entries(profile);
      // Durable capture precedes all network I/O, retaining offline edits.
      await repository.database.transaction(() async {
        check();
        _capture(cache, device, await _locals(profile, sources, entries));
        await repository.savePreference(profile, cacheKey, cache.toJson());
      });
      final listed = await store.list(cipher.namespace);
      check();
      final latest = <String, int>{};
      for (final f in listed) {
        if (f.sequence > (latest[f.device] ?? -1)) latest[f.device] = f.sequence;
        if (f.device == device && f.sequence > cache.sequence) cache.sequence = f.sequence;
      }
      if (latest.length > 128 || latest.length == 128 && !latest.containsKey(device)) {
        throw const SourceException(SourceFailure.invalidData);
      }
      final remote = SyncDocument();
      for (final f in listed.where((f) => latest[f.device] == f.sequence)) {
        check();
        final document = await cipher.open(await store.read(f), f.name);
        check();
        remote.merge(document);
      }
      // Capture ticks arriving during pull against the pre-pull basis.
      await repository.database.transaction(() async {
        check();
        _capture(cache, device, await _locals(profile, sources, entries));
        cache.document.merge(remote);
        await _apply(profile, cache, _identities(sources, entries), activeKeys);
        check();
        await repository.savePreference(profile, cacheKey, cache.toJson());
      });
      final digest = _hash(cache.document.toJson());
      if (digest != cache.published || !latest.containsKey(device)) {
        cache.sequence++;
        if (cache.sequence > 9999999999999999) throw const SourceException(SourceFailure.invalidData);
        check();
        await repository.savePreference(profile, cacheKey, cache.toJson());
        final name = SyncFile.filename(cipher.namespace, device, cache.sequence);
        final encrypted = await cipher.seal(cache.document, name);
        check();
        await store.create(name, encrypted);
        check();
        cache.published = digest;
        await repository.savePreference(profile, cacheKey, cache.toJson());
        final owned = listed.where((f) => f.device == device).toList()
          ..sort((a,b) => b.sequence.compareTo(a.sequence));
        // Keep one previous successful snapshot, and never prune other devices.
        for (final old in owned.skip(1)) {
          check();
          try {
            await store.delete(old);
          } on SourceException catch (e) {
            if (e.reason == SourceFailure.cancelled) rethrow;
          }
        }
      }
      check();
      lastSuccess = DateTime.now();
    } on SourceException catch (e) {
      failure = e.reason;
      rethrow;
    } catch (_) {
      failure = SourceFailure.unavailable;
      rethrow;
    } finally {
      running = false;
    }
  }

  Future<void> resolve({
    required String profile, required PublicationSyncConfig config,
    required String key, required SyncVersion selected,
    required List<FileSource> sources, required Set<String> activeKeys,
    required void Function() check,
  }) async {
    final cacheKey = _cacheKey(SyncCipher(config.code).namespace);
    await repository.database.transaction(() async {
      check();
      final cache = _SyncCache(await repository.preference(profile, cacheKey));
      final current = cache.document.records[key] ?? [];
      if (!current.any((v) => canonicalSyncJson(v.toJson()) == canonicalSyncJson(selected.toJson()))) {
        throw const SourceException(SourceFailure.conflict);
      }
      final device = (await repository.preference(profile, 'publication-sync-device-v1'))['id'] as String;
      cache.document.edit(key, device, selected.value, joinedClock(current));
      cache.observed.remove(key);
      await _apply(profile, cache, _identities(sources, await repository.entries(profile)), activeKeys);
      check();
      await repository.savePreference(profile, cacheKey, cache.toJson());
    });
  }
}

/// Parse source time; long books may exceed 24 hours. Invalid input never
/// silently turns into a seek to the beginning.
int? parseListeningTime(String input) {
  final parts = input.trim().split(':');
  if (parts.length < 2 || parts.length > 3 ||
      parts.any((p) => !RegExp(r'^\d{1,5}$').hasMatch(p))) return null;
  final values = parts.map(int.parse).toList();
  if (values.last >= 60 || parts.length == 3 && values[1] >= 60) return null;
  final seconds = parts.length == 3
      ? values[0] * 3600 + values[1] * 60 + values[2]
      : values[0] * 60 + values[1];
  return seconds * 1000;
}

import 'source_models.dart';
enum PublicationSort { title, author, narrator, series, recent }
enum PublicationStatus { all, unstarted, inProgress, finished }

List<SourceEntry> organizePublications(List<SourceEntry> entries, List<PublicationProgress> progress, {
  PublicationSort sort = PublicationSort.title,
  PublicationStatus status = PublicationStatus.all,
  PublicationMode? mode,
}) {
  final latest = <String, PublicationProgress>{};
  for (final p in progress) {
    if (mode != null && p.mode != mode) continue;
    if ((latest[p.entryKey]?.updatedAt ?? -1) < p.updatedAt) latest[p.entryKey] = p;
  }
  bool started(PublicationProgress? p) =>
      p != null && (p.positionMs > 0 || p.fraction > 0 || p.locator != null);
  final result = entries.where((e) {
    if (e.isFolder) return true;
    final p = latest[e.key];
    return switch (status) {
      PublicationStatus.all => true,
      PublicationStatus.unstarted => p?.finished != true && !started(p),
      PublicationStatus.inProgress => p?.finished != true && started(p),
      PublicationStatus.finished => p?.finished == true,
    };
  }).toList();
  int text(String a, String b) => a.toLowerCase().compareTo(b.toLowerCase());
  result.sort((a, b) {
    if (a.isFolder != b.isFolder) return a.isFolder ? -1 : 1;
    final primary = switch (sort) {
      PublicationSort.title => text(a.title, b.title),
      PublicationSort.author => text(a.author, b.author),
      PublicationSort.narrator => text(a.narrator, b.narrator),
      PublicationSort.series => text(a.series, b.series) != 0
          ? text(a.series, b.series)
          : (a.seriesOrder ?? double.infinity).compareTo(b.seriesOrder ?? double.infinity),
      PublicationSort.recent => (latest[b.key]?.updatedAt ?? 0).compareTo(latest[a.key]?.updatedAt ?? 0),
    };
    if (primary != 0) return primary;
    final title = text(a.title, b.title);
    return title != 0 ? title : a.key.compareTo(b.key);
  });
  return result;
}

