class SourceSyncScreen extends StatefulWidget {
  const SourceSyncScreen({super.key});
  @override
  State<SourceSyncScreen> createState() => _SourceSyncScreenState();
}
class _SourceSyncScreenState extends State<SourceSyncScreen> {
  final _code = TextEditingController(), _folder = TextEditingController();
  String? _source;
  bool _busy = false, _reveal = false, _loaded = false;
  Object? _error;
  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_loaded) return;
    _loaded = true;
    final config = context.read<SourceController>().syncConfig;
    _source = config?.sourceId;
    _code.text = config?.code ?? '';
    _folder.text = config?.folder ?? '.plezyng-sync';
  }
  @override
  void dispose() {
    _code.dispose();
    _folder.dispose();
    super.dispose();
  }
  Future<void> _action(Future<void> Function() action) async {
    setState(() { _busy = true; _error = null; });
    try {
      await action();
    } catch (e) {
      if (mounted) setState(() => _error = e);
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }
  String _choice(SyncVersion version) {
    final data = sourceMap(version.value['data']);
    if (version.value['type'] == 'annotation') {
      return data['deleted'] == true
          ? t.audiobook.deletedBookmark
          : '${data['note'] ?? ''} ${data['quote'] ?? ''}'.trim();
    }
    if (data['finished'] == true) return t.audiobook.finished;
    if (data['mode'] == 'reading') {
      return t.audiobook.readingPosition(percent: ((data['fraction'] as num? ?? 0) * 100).round());
    }
    return sourceTime(sourceInt(data['positionMs']) ?? 0);
  }
  @override
  Widget build(BuildContext context) {
    final controller = context.watch<SourceController>();
    final sources = controller.sources.where((s) => ProviderSyncStore.supports(s.kind)).toList();
    final selected = sources.where((s) => s.id == _source).firstOrNull;
    final configured = controller.syncConfig != null;
    final sync = controller.cloudSync;
    return FocusedScrollScaffold(
      title: Text(t.audiobook.syncTitle),
      slivers: [SliverToBoxAdapter(child: Center(child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 720),
        child: Padding(padding: const EdgeInsets.all(24), child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(t.audiobook.syncHelp),
            const SizedBox(height: 24),
            if (sources.isEmpty) Text(t.audiobook.addSyncSource)
            else DropdownButtonFormField<String>(
              isExpanded: true, initialValue: selected?.id,
              decoration: InputDecoration(labelText: t.audiobook.syncDestination),
              items: [for (final s in sources) DropdownMenuItem(value: s.id,
                child: Text('${s.name} · ${sourceKindName(s.kind)}', overflow: TextOverflow.ellipsis))],
              onChanged: _busy ? null : (v) => setState(() => _source = v),
            ),
            if (selected?.kind == FileSourceKind.webdav || selected?.kind == FileSourceKind.s3) ...[
              const SizedBox(height: 16),
              TextField(controller: _folder, enabled: !_busy, autocorrect: false,
                decoration: InputDecoration(labelText: t.audiobook.syncFolder,
                  helperText: t.audiobook.syncFolderHelp, helperMaxLines: 3)),
            ],
            const SizedBox(height: 16),
            TextField(controller: _code, enabled: !_busy, obscureText: !_reveal,
              autocorrect: false, enableSuggestions: false,
              decoration: InputDecoration(labelText: t.audiobook.syncCode,
                helperText: t.audiobook.syncCodeHelp, helperMaxLines: 4,
                suffixIcon: IconButton(tooltip: t.audiobook.showCode,
                  onPressed: () => setState(() => _reveal = !_reveal),
                  icon: AppIcon(_reveal ? Symbols.visibility_off_rounded : Symbols.visibility_rounded)))),
            if (!configured) Align(alignment: AlignmentDirectional.centerStart,
              child: TextButton.icon(
                onPressed: _busy ? null : () => setState(() {
                  _code.text = SyncCipher.newCode(); _reveal = true;
                }),
                icon: const AppIcon(Symbols.add_rounded), label: Text(t.audiobook.newSyncCode))),
            const SizedBox(height: 16),
            FilledButton(
              onPressed: _busy || selected == null ? null : () => _action(
                () => controller.configureCloudSync(PublicationSyncConfig(
                  sourceId: selected.id, code: _code.text.trim(), folder: _folder.text.trim()))),
              child: Text(t.audiobook.saveSync)),
            if (configured) ...[
              const SizedBox(height: 12),
              OutlinedButton.icon(onPressed: _busy ? null : () => _action(controller.sync),
                icon: const AppIcon(Symbols.sync_rounded), label: Text(t.fileSources.sync)),
              TextButton(onPressed: _busy ? null : () => _action(
                () => controller.configureCloudSync(null)), child: Text(t.audiobook.disableSync)),
            ],
            if (_busy || sync.running) const LinearProgressIndicator(),
            if (_error != null || sync.failure != null) Padding(
              padding: const EdgeInsets.symmetric(vertical: 16),
              child: Text(sourceFailureText(_error ?? SourceException(sync.failure!)))),
            if (sync.lastSuccess != null) Padding(
              padding: const EdgeInsets.symmetric(vertical: 8),
              child: Text(t.audiobook.lastSynced(time: MaterialLocalizations.of(context)
                .formatTimeOfDay(TimeOfDay.fromDateTime(sync.lastSuccess!.toLocal()))))),
            Text(t.audiobook.syncPrivacy, style: Theme.of(context).textTheme.bodySmall),
            if (sync.conflicts.isNotEmpty) ...[
              const SizedBox(height: 32),
              Text(t.audiobook.syncConflicts, style: Theme.of(context).textTheme.titleLarge),
              const SizedBox(height: 8),
              Text(t.audiobook.conflictHelp),
              for (final conflict in sync.conflicts.values) Padding(
                padding: const EdgeInsets.symmetric(vertical: 16),
                child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                  Text(conflict.entry.title, style: Theme.of(context).textTheme.titleMedium),
                  for (final version in conflict.values) OutlinedButton(
                    onPressed: _busy ? null : () => _action(() async {
                      await controller.stopPlayback?.call();
                      await controller.resolveCloudConflict(conflict.key, version);
                    }),
                    child: Text(_choice(version).isEmpty ? t.fileSources.bookmark : _choice(version),
                      maxLines: 4, overflow: TextOverflow.ellipsis)),
                ])),
            ],
          ],
        )),
      )))],
    );
  }
}

import 'package:flutter_test/flutter_test.dart';
import 'package:plezy/sources/source_models.dart';
import 'package:plezy/sources/sync/sync_document.dart';
import 'package:plezy/sources/sync/sync_store.dart';

void main() {
  final a = 'a' * 32, b = 'b' * 32, key = 'f' * 64;
  test('merge commutes and repeats safely; reset beats observed progress', () {
    final one = SyncDocument()..edit(key, a, {'position': 100}, {});
    final two = SyncDocument.fromJson(one.toJson());
    two.edit(key, b, {'position': 0}, joinedClock(two.records[key]!));
    final left = SyncDocument()..merge(one)..merge(two)..merge(one);
    final right = SyncDocument()..merge(two)..merge(one)..merge(two);
    expect(canonicalSyncJson(left.toJson()), canonicalSyncJson(right.toJson()));
    expect(left.records[key]!.single.value['position'], 0);
    expect(left.conflicted(key), isFalse);
  });
  test('independent offline edits retained until an explicit choice', () {
    final one = SyncDocument()..edit(key, a, {'position': 100}, {});
    final two = SyncDocument()..edit(key, b, {'position': 20}, {});
    one.merge(two);
    expect(one.conflicted(key), isTrue);
    one.edit(key, a, {'position': 20}, joinedClock(one.records[key]!));
    two.merge(one);
    expect(two.records[key]!.single.value['position'], 20);
    expect(two.conflicted(key), isFalse);
  });
  test('deferred remote data is not an ancestor of local edits', () {
    final doc = SyncDocument();
    final basis = doc.edit(key, a, {'position': 100}, {}).clock;
    final remote = SyncDocument.fromJson(doc.toJson());
    remote.edit(key, b, {'position': 200}, joinedClock(remote.records[key]!));
    doc.merge(remote);
    doc.edit(key, a, {'position': 110}, basis);
    expect(doc.conflicted(key), isTrue);
  });
  test('equal vector with different data is corruption', () {
    final doc = SyncDocument()..edit(key, a, {'position': 1}, {});
    expect(() => doc.merge(SyncDocument({
      key: [SyncVersion({a: 1}, {'position': 2})],
    })), throwsA(isA<SourceException>()));
  });
  test('encryption requires the correct key and authenticated filename', () async {
    final cipher = SyncCipher(SyncCipher.newCode());
    final doc = SyncDocument()..edit(key, a, {'note': 'private annotation'}, {});
    final name = SyncFile.filename(cipher.namespace, a, 1);
    final encrypted = await cipher.seal(doc, name);
    expect(encrypted, isNot(contains('private annotation')));
    expect(canonicalSyncJson((await cipher.open(encrypted, name)).toJson()),
      canonicalSyncJson(doc.toJson()));
    await expectLater(cipher.open(encrypted, '$name.changed'), throwsA(isA<SourceException>()));
    await expectLater(SyncCipher(SyncCipher.newCode()).open(encrypted, name),
      throwsA(isA<SourceException>()));
    await expectLater(cipher.open('{}', name), throwsA(isA<SourceException>()));
  });
  test('invalid keys, schemas, record IDs and clocks are rejected', () {
    expect(() => SyncCipher('password'), throwsA(isA<SourceException>()));
    expect(() => SyncDocument.fromJson({'version': 2, 'records': {}}),
      throwsA(isA<SourceException>()));
    expect(() => SyncDocument.fromJson({'version': 1, 'records': {'../escape': []}}),
      throwsA(isA<SourceException>()));
    expect(() => SyncVersion.fromJson({'clock': {a: -1}, 'value': {}}),
      throwsA(isA<SourceException>()));
  });
}

import 'dart:convert';
import 'package:drift/native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:plezy/sources/source_database.dart';
import 'package:plezy/sources/source_models.dart';
import 'package:plezy/sources/sync/publication_sync.dart';
import 'package:plezy/sources/sync/sync_document.dart';
import 'package:plezy/sources/sync/sync_store.dart';

class MemorySyncStore implements SyncStore {
  final files = <String, String>{};
  bool offline = false;
  Future<void> Function()? onRead;
  @override
  Future<List<SyncFile>> list(String namespace) async {
    if (offline) throw const SourceException(SourceFailure.unavailable);
    return files.keys.where((n) => n.contains(namespace)).map((n) => SyncFile(n, n)).toList();
  }
  @override
  Future<String> read(SyncFile file) async {
    await onRead?.call();
    return files[file.id]!;
  }
  @override
  Future<void> create(String name, String text) async {
    if (offline) throw const SourceException(SourceFailure.unavailable);
    files[name] = text;
  }
  @override
  Future<void> delete(SyncFile file) async { files.remove(file.id); }
}

void main() {
  const audio = PublicationFile(id: 'audio-id', name: 'book.m4b', mimeType: 'audio/mp4',
    size: 500000, revision: 'v1', durationMs: 300000);
  const ebook = PublicationFile(id: 'epub-id', name: 'book.epub',
    mimeType: 'application/epub+zip', size: 1000, revision: 'v1');
  final edition = sourceDigest(jsonEncode([audio.fingerprint]));
  late SourceRepository repoA, repoB;
  late PublicationSync a, b;
  late MemorySyncStore store;
  late PublicationSyncConfig config;
  const sourceA = FileSource(id: 'connection-A', profileId: 'profile-A',
    kind: FileSourceKind.googleDrive, name: 'Books');
  const sourceB = FileSource(id: 'connection-B', profileId: 'profile-B',
    kind: FileSourceKind.googleDrive, name: 'My Drive');
  const entryA = SourceEntry(sourceId: 'connection-A', id: 'same-provider-book',
    title: 'Book', kind: SourceItemKind.audiobook, files: [audio, ebook]);
  const entryB = SourceEntry(sourceId: 'connection-B', id: 'same-provider-book',
    title: 'Book', kind: SourceItemKind.audiobook, files: [audio, ebook]);
  String localKey(SourceEntry entry) => PublicationProgress(entryKey: entry.key,
    edition: edition, mode: PublicationMode.listening, session: '').key;
  Future<void> position(SourceRepository repo, String profile, SourceEntry entry, int ms,
    {bool finished = false}) async {
    final old = await repo.progress(profile, localKey(entry));
    await repo.saveProgress(profile, PublicationProgress(
      entryKey: entry.key, edition: edition, mode: PublicationMode.listening,
      session: 'session', revision: old?.revision ?? 0, positionMs: ms,
      filePositionMs: ms, fraction: ms / 300000, finished: finished));
  }
  Future<int?> at(SourceRepository repo, String profile, SourceEntry entry) async =>
      (await repo.progress(profile, localKey(entry)))?.positionMs;
  Future<void> runA({Set<String> active = const {}, void Function()? check}) => a.run(
    profile: 'profile-A', sources: [sourceA], config: config, store: store,
    activeKeys: active, check: check ?? () {});
  Future<void> runB() => b.run(profile: 'profile-B', sources: [sourceB],
    config: config, store: store, activeKeys: {}, check: () {});
  setUp(() async {
    SourceRepository repo() => SourceRepository(SourceDatabase(NativeDatabase.memory()),
      protect: (s) async => s, reveal: (s) async => s);
    repoA = repo(); repoB = repo();
    a = PublicationSync(repoA); b = PublicationSync(repoB);
    store = MemorySyncStore();
    config = PublicationSyncConfig(sourceId: sourceA.id, code: SyncCipher.newCode());
    await repoA.cacheEntries('profile-A', [entryA]);
    await repoB.cacheEntries('profile-B', [entryB]);
